import type { ExposureStatus } from '../types';

export interface DualZoneCalibrationSample {
  sampleId: string;
  block: string;
  replicate: number;
  h2sPpm: number;
  durationH: number;
  exposureProfile: string;
  trueDosePpmH: number;
  tempC: number;
  rhPct: number;
  sealedPouch: boolean;
  stripAgeDays: number;
  lightKluxH: number;
  uvFilm: boolean;
  readDelayH: number;
  interferent: string;
  agZone: {
    L: number;
    a: number;
    b: number;
    r: number;
    g: number;
    bCol: number;
    hex: string;
    deltaE: number;
    fraction: number;
  };
  cuZone: {
    L: number;
    a: number;
    b: number;
    r: number;
    g: number;
    bCol: number;
    hex: string;
    deltaE: number;
    fraction: number;
  };
  ctrlPatchFrac: number;
  sealDot: string;
  estAgZonePpmH: number | null;
  estCuZonePpmH: number | null;
  estDosePpmH: number;
  ci95Low: number;
  ci95High: number;
  estErrorPct: number;
  qaFlag: string;
  safetyStatus: ExposureStatus;
  
  // Backward-compatible compatibility fields:
  targetDose: number;
  gasConc: number;
  exposureTime: number;
  rh: number;
  shelfAge: number;
  lab: { L: number; a: number; b: number };
  rawColorString: string;
  deltaE: number;
  expiryStatus: string;
  actionFlag: string;
  dataSource: string;
  hexColor: string;
  cuHexColor: string;
  zoneA_hexColor?: string;
  zoneB_hexColor?: string;
  zoneA_deltaE?: number;
  zoneB_deltaE?: number;
  dose_ppm_h_zoneA?: number;
  dose_ppm_h_zoneB?: number;
  seal_breach_detected?: boolean;
  light_exposure_warning?: boolean;
}

export type CalibrationSample = DualZoneCalibrationSample;

export function toHex(r: number, g: number, b: number): string {
  const clamp = (val: number) => Math.max(0, Math.min(255, Math.round(val)));
  const h = (n: number) => clamp(n).toString(16).padStart(2, '0');
  return '#' + h(r) + h(g) + h(b);
}

export function mapDoseToSafetyStatus(dose: number, qaFlag: string, sealDot: string): ExposureStatus {
  if (qaFlag === 'SEAL_BROKEN' || sealDot.includes('BLUE') || sealDot.includes('breached')) return 'REVIEW';
  if (qaFlag === 'ABOVE_RANGE' || dose >= 15.0) return 'REVIEW';
  if (dose >= 5.0 || qaFlag === 'LIGHT_OR_AGE_WARNING') return 'MONITOR';
  return 'NORMAL';
}

